import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 다운로드 대상 화면 구분 값은 문서에 없어 아래 4개로 정하고, menu.module_link 가 이 값과 같은 메뉴의 권한(menu_permission)을 기준으로 한다.
// 가정: 모든 대상 화면에는 사원 이름 등 개인정보가 들어 있으므로 다운로드마다 접속·사용 로그(개인정보열람)를 남긴다.
// 가정: 엑셀 파일은 SpreadsheetML(XML) 문자열로 만들어 file 필드에 담는다.
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^\d+$/;

// 공통: 권한 범위(전체·부서·개인)와 조회 조건
const SCOPE_SQL =
  '(:scope = \'전체\'' +
  ' OR (:scope = \'부서\' AND e.department_id = (SELECT department_id FROM employee WHERE employee_id = CAST(:userId AS bigint)))' +
  ' OR (:scope = \'개인\' AND e.employee_id = CAST(:userId AS bigint)))';
const FILTER_SQL =
  ' AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))' +
  ' AND (CAST(:employeeId AS bigint) IS NULL OR e.employee_id = CAST(:employeeId AS bigint))';

interface ScreenDef {
  columns: [string, string][];
  sql: string;
}

const SCREENS: Record<string, ScreenDef> = {
  ATTENDANCE_DAILY: {
    columns: [
      ['employee_name', '사원'],
      ['work_date', '근무일자'],
      ['clock_in_at', '출근시각'],
      ['clock_out_at', '퇴근시각'],
      ['closing_status', '마감 상태'],
    ],
    sql:
      'SELECT e.name AS employee_name, CAST(d.work_date AS text) AS work_date,' +
      ' CAST(d.clock_in_at AS text) AS clock_in_at, CAST(d.clock_out_at AS text) AS clock_out_at,' +
      ' d.closing_status AS closing_status' +
      ' FROM attendance_daily d JOIN employee e ON e.employee_id = d.employee_id' +
      ' WHERE ' + SCOPE_SQL + FILTER_SQL +
      ' AND (CAST(:startDate AS date) IS NULL OR d.work_date >= CAST(:startDate AS date))' +
      ' AND (CAST(:endDate AS date) IS NULL OR d.work_date <= CAST(:endDate AS date))' +
      ' ORDER BY d.work_date, e.name',
  },
  ATTENDANCE_REQUEST: {
    columns: [
      ['employee_name', '신청자'],
      ['type_name', '근태항목'],
      ['start_date', '시작일'],
      ['end_date', '종료일'],
      ['reason', '사유'],
      ['approval_status', '결재 진행 상태'],
    ],
    sql:
      'SELECT e.name AS employee_name, t.type_name AS type_name, CAST(r.start_date AS text) AS start_date,' +
      ' CAST(r.end_date AS text) AS end_date, r.reason AS reason, r.approval_status AS approval_status' +
      ' FROM attendance_request r JOIN employee e ON e.employee_id = r.employee_id' +
      ' JOIN attendance_type t ON t.attendance_type_id = r.attendance_type_id' +
      ' WHERE ' + SCOPE_SQL + FILTER_SQL +
      ' AND (CAST(:startDate AS date) IS NULL OR r.end_date >= CAST(:startDate AS date))' +
      ' AND (CAST(:endDate AS date) IS NULL OR r.start_date <= CAST(:endDate AS date))' +
      ' ORDER BY r.start_date, e.name',
  },
  ANNUAL_LEAVE: {
    columns: [
      ['employee_name', '사원'],
      ['leave_year', '대상 연도'],
      ['granted_days', '생성 일수'],
      ['adjusted_days', '조정 일수'],
      ['used_days', '사용 일수'],
      ['confirm_status', '확정 여부'],
    ],
    sql:
      'SELECT e.name AS employee_name, a.leave_year AS leave_year, a.granted_days AS granted_days,' +
      ' a.adjusted_days AS adjusted_days, a.used_days AS used_days, a.confirm_status AS confirm_status' +
      ' FROM annual_leave a JOIN employee e ON e.employee_id = a.employee_id' +
      ' WHERE ' + SCOPE_SQL + FILTER_SQL +
      ' AND (CAST(:startDate AS date) IS NULL OR a.leave_year >= EXTRACT(year FROM CAST(:startDate AS date)))' +
      ' AND (CAST(:endDate AS date) IS NULL OR a.leave_year <= EXTRACT(year FROM CAST(:endDate AS date)))' +
      ' ORDER BY a.leave_year, e.name',
  },
  ACCESS_LOG: {
    columns: [
      ['employee_name', '사원'],
      ['event_type', '이벤트 구분'],
      ['accessed_at', '접속·사용 일시'],
      ['login_ip', '접속 IP'],
      ['login_type', '로그인 구분'],
    ],
    sql:
      'SELECT e.name AS employee_name, l.event_type AS event_type, CAST(l.accessed_at AS text) AS accessed_at,' +
      ' l.login_ip AS login_ip, l.login_type AS login_type' +
      ' FROM access_log l JOIN employee e ON e.employee_id = l.employee_id' +
      ' WHERE ' + SCOPE_SQL + FILTER_SQL +
      ' AND (CAST(:startDate AS date) IS NULL OR CAST(l.accessed_at AS date) >= CAST(:startDate AS date))' +
      ' AND (CAST(:endDate AS date) IS NULL OR CAST(l.accessed_at AS date) <= CAST(:endDate AS date))' +
      ' ORDER BY l.accessed_at DESC',
  },
};

function xmlText(value: unknown): string {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function buildExcel(columns: [string, string][], rows: Array<Record<string, unknown>>): string {
  let xml = '<?xml version=\'1.0\' encoding=\'UTF-8\'?>\n';
  xml += '<Workbook xmlns=\'urn:schemas-microsoft-com:office:spreadsheet\' xmlns:ss=\'urn:schemas-microsoft-com:office:spreadsheet\'>\n';
  xml += '<Worksheet ss:Name=\'조회 결과\'><Table>\n';
  xml += '<Row>';
  for (const column of columns) {
    xml += '<Cell><Data ss:Type=\'String\'>' + xmlText(column[1]) + '</Data></Cell>';
  }
  xml += '</Row>\n';
  for (const row of rows) {
    xml += '<Row>';
    for (const column of columns) {
      xml += '<Cell><Data ss:Type=\'String\'>' + xmlText(row[column[0]]) + '</Data></Cell>';
    }
    xml += '</Row>\n';
  }
  xml += '</Table></Worksheet></Workbook>';
  return xml;
}

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return String(value);
}

@Controller('api/v1')
export class FnSfr01808Controller {
  @Get('/excel-downloads')
  async downloadQueryResultExcel(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자', '자원 담당자', '시스템 관리자');
    const data = checks.queryOf(req.query);
    const target = optionalText(data['targetScreen']);
    if (target === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '다운로드 대상 화면을 선택해 주세요.');
    }
    const startDate = optionalText(data['startDate']);
    const endDate = optionalText(data['endDate']);
    const departmentId = optionalText(data['departmentId']);
    const employeeId = optionalText(data['employeeId']);
    if (startDate !== null && !DATE_PATTERN.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (endDate !== null && !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다.');
    }
    if (startDate !== null && endDate !== null && startDate > endDate) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일은 종료일보다 늦을 수 없습니다.');
    }
    if (departmentId !== null && !ID_PATTERN.test(departmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서 값이 올바르지 않습니다.');
    }
    if (employeeId !== null && !ID_PATTERN.test(employeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사원 값이 올바르지 않습니다.');
    }
    if (!Object.prototype.hasOwnProperty.call(SCREENS, target)) {
      throw new ApiError(422, 'INVALID_TARGET_SCREEN', '지원하지 않는 다운로드 대상 화면입니다.');
    }
    const screen = SCREENS[target];
    const loginIp = typeof req.ip === 'string' && req.ip !== '' ? req.ip : '0.0.0.0';

    return transaction(async (db) => {
      const permissions = await db.query(
        'SELECT mp.view_scope AS view_scope, m.menu_id AS menu_id' +
          ' FROM menu_permission mp JOIN menu m ON m.menu_id = mp.menu_id' +
          ' WHERE mp.employee_id = CAST(:userId AS bigint) AND mp.use_yn = \'사용\'' +
          ' AND m.use_yn = \'사용\' AND m.module_link = :target',
        { userId: user.id, target },
      );
      if (permissions.length === 0) {
        throw new ApiError(403, 'FORBIDDEN', '해당 조회 메뉴의 조회 권한이 없습니다.');
      }
      let scope = '개인';
      for (const permission of permissions) {
        if (permission['view_scope'] === '전체') {
          scope = '전체';
        } else if (permission['view_scope'] === '부서' && scope !== '전체') {
          scope = '부서';
        }
      }
      const rows = await db.query(screen.sql, {
        scope,
        userId: user.id,
        startDate,
        endDate,
        departmentId,
        employeeId,
      });
      if (rows.length === 0) {
        throw new ApiError(404, 'NO_DATA_TO_DOWNLOAD', '다운로드할 데이터가 없습니다.');
      }
      let file = '';
      try {
        file = buildExcel(screen.columns, rows);
      } catch (e) {
        throw new ApiError(502, 'EXCEL_GENERATION_FAILED', '엑셀 파일을 만들지 못했습니다. 잠시 후 다시 시도해 주세요.');
      }
      await db.execute(
        'INSERT INTO access_log (employee_id, menu_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at)' +
          ' VALUES (CAST(:userId AS bigint), CAST(:menuId AS bigint), \'개인정보열람\', now(), :loginIp, \'웹\', :targetInfo, now(), now())',
        {
          userId: user.id,
          menuId: permissions[0]['menu_id'],
          loginIp,
          targetInfo: target,
        },
      );
      return { file };
    });
  }
}

