import { useState } from 'react';
import { Band, DataTable, DateInput, DateText, Drawer, Field, Form, LookupSelect, Num, Select, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

const SCREEN_OPTIONS: [string, string][] = [
  ['ATTENDANCE_DAILY', '일별 근태'],
  ['ATTENDANCE_REQUEST', '근태 신청'],
  ['ANNUAL_LEAVE', '연차'],
  ['ACCESS_LOG', '접속·사용 로그'],
];

function screenName(value: unknown): string {
  const found = SCREEN_OPTIONS.find((option) => option[0] === value);
  return found ? found[1] : String(value);
}

export default function FnSfr01808Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [history, setHistory] = useState<Row[]>([]);
  const [targetScreen, setTargetScreen] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');

  const download = async () => {
    if (targetScreen === '') {
      throw new Error('다운로드 대상 화면을 선택해 주세요.');
    }
    const result = await call<Row>('GET', '/excel-downloads', role, undefined, {
      targetScreen,
      startDate,
      endDate,
      departmentId,
      employeeId,
    });
    const file = String(result['file'] ?? '');
    const blob = new Blob([file], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = targetScreen + '.xls';
    link.click();
    URL.revokeObjectURL(url);
    setHistory([
      {
        id: history.length + 1,
        targetScreen,
        startDate,
        endDate,
        size: file.length,
        requestedAt: new Date().toISOString(),
      },
      ...history,
    ]);
    notify('엑셀 파일을 내려받았습니다.');
    setOpen(false);
  };

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>이번 접속 다운로드</h2>
        <Tiles items={[['다운로드 건수', <Num value={history.length} />]]} />
      </section>
      <section className='box span-8'>
        <h2>다운로드 내역</h2>
        <Band total={history.length}>
          <button type='button' onClick={() => setOpen(true)}>엑셀 다운로드</button>
        </Band>
        <DataTable
          rows={history}
          empty='다운로드한 내역이 없습니다.'
          columns={[
            { key: 'targetScreen', label: '다운로드 대상 화면 구분', render: (row) => screenName(row['targetScreen']) },
            { key: 'startDate', label: '조회 시작일', render: (row) => <DateText value={row['startDate']} /> },
            { key: 'endDate', label: '조회 종료일', render: (row) => <DateText value={row['endDate']} /> },
            { key: 'size', label: '파일 크기', render: (row) => <Num value={row['size']} /> },
            { key: 'requestedAt', label: '요청 시각', render: (row) => <DateText value={row['requestedAt']} time /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title='조회 결과 엑셀 다운로드' onClose={() => setOpen(false)}>
          <Form onSubmit={download} submit='다운로드'>
            <Field label='다운로드 대상 화면 구분' required>
              <Select value={targetScreen} onChange={setTargetScreen} options={SCREEN_OPTIONS} />
            </Field>
            <Field label='조회 시작일'>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label='조회 종료일'>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label='부서'>
              <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} />
            </Field>
            <Field label='사원'>
              <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
